def usage(code: int = 2) -> None:
    sys.stderr.write(__doc__.split("Usage:", 1)[1].split("Check rows", 1)[0])
    sys.exit(code)


def main() -> None:
    args = sys.argv[1:]
    guideline_out = fitness_out = None
    do_check, positional = False, []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ("--guideline", "--fitness"):
            if i + 1 >= len(args):
                usage()
            if arg == "--guideline":
                guideline_out = pathlib.Path(args[i + 1])
            else:
                fitness_out = pathlib.Path(args[i + 1])
            i += 2
        elif arg == "--check":
            do_check = True; i += 1
        elif arg.startswith("--"):
            usage()
        else:
            positional.append(arg); i += 1
    if len(positional) != 1:
        usage()
    typedef = pathlib.Path(positional[0])
    try:
        if do_check:
            for row in check(typedef, guideline_out, fitness_out):

        skill_out.parent.mkdir(parents=True, exist_ok=True)
        skill_out.write_text(
            generate_skill(front, spec, purpose, guiding, diagram, digest, source_rel)
        )
        print(f"{skill_out}: generated from {front['id']} (digest {digest})")


def main() -> None:
    args = sys.argv[1:]
    skill_out = None
    if "--skill" in args:
        i = args.index("--skill")
        if i + 1 >= len(args):
            sys.exit(__doc__.split("Usage:", 1)[1].rstrip())
        skill_out = pathlib.Path(args[i + 1])
        args = args[:i] + args[i + 2:]
    if len(args) != 1:
        sys.exit(__doc__.split("Usage:", 1)[1].rstrip())
    source = pathlib.Path(args[0])
    try:
        compile_definition(source, skill_out)
    except SystemExit:
        raise
    except Exception as exc:  # noqa: BLE001 — a definition that does not
        # compile is a one-line reason on stderr, never a traceback
        sys.exit(f"{source}: does not compile: {type(exc).__name__}: {one_line(exc)}")


if __name__ == "__main__":
    main()
